"""RoboPaint execution record. All movement uses the public robot client."""
import sys,json,time,math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output'); RUNS=Path('/app/runs')
Q=[0,1,0,0]
SURFACE=.0202
SCALE=.227185/1024

def uv(u,v,z): return [-.1+(512-v)*SCALE,(512-u)*SCALE,z,*Q]

class Painter:
 def __init__(self):
  self.r=Robot(); self.o=self.r.get_obs(cameras=[]); self.p=np.array(self.o.meta['proprio']['now'][7:14]); self.i=len(list(RUNS.glob('call_*')))
 def send(self,poses,note='',cams=['practice_cam']):
  poses=np.array(poses)
  for a in range(0,len(poses),180):
   chunk=poses[a:a+180]; self.i+=1
   folder=RUNS/f'call_{self.i:04d}';folder.mkdir(exist_ok=True)
   np.save(folder/'command.npy',chunk)
   (folder/'note.txt').write_text(note)
   res=self.r.submit('ee_pose',chunk,dt=.05,cameras=cams,video='none',note=note)
   res.save(str(folder));self.p=np.array(res.meta['proprio']['now'][7:14])
   print(self.i,note,'tip',self.p[:3].round(5),'plan',res.meta.get('plan'),'left',res.meta.get('time_left_s'),flush=True)
   for k,v in res.last.items():Image.fromarray(v).save(ROOT/(k+'.png'))
  return res
 def move(self,p,t=1,note='travel'):
  p=np.array(p); n=max(1,int(t/.05));return self.send(np.linspace(self.p,p,n+1)[1:],note)
 def hold(self,t=.3):return self.send([self.p]*int(t/.05),'settle')
 def observe(self):
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save('/app/runs/latest')
  for k,v in o.last.items():Image.fromarray(v).save(ROOT/(k+'.png'))
  return o
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='park':p.move([-.1,.25,.10,*Q],3);p.observe()
 elif sys.argv[1]=='pose':p.move([*map(float,sys.argv[2:5]),*Q],float(sys.argv[5]) if len(sys.argv)>5 else 2);p.observe()
 elif sys.argv[1]=='obs':p.observe()
